  "implementation": "def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    fixed = False
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old = p['old']
            new = p['new']
            if old in text:
                text = text.replace(old, new)
                applications.append(p['name'])
                changed = True
        if not changed:
            fixed = True
            break
    return {
        'applications': applications,
        'fixed_point': fixed,
        'text': text
    }"
}
